<script setup lang="ts">import {computed,onMounted,ref,watch} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {api,idr} from '../api';import {useSession} from '../stores';const route=useRoute(),router=useRouter(),session=useSession(),data=ref<any>(null),error=ref(''),showProduct=ref(false),form=ref({name:'',sku:'',description:'',categoryId:'',price:0,stock:0,isActive:true,imageUrl:''});const section=computed(()=>String(route.params.section??'overview'));async function load(){error.value='';if(!session.user){await session.load();if(!session.user)return router.push('/login')}if(session.user.role!=='ADMIN')return router.push('/');try{if(section.value==='overview')data.value=await api('/admin/dashboard/overview');else data.value=await api(`/admin/${section.value}`)}catch(e:any){error.value=e.message}}onMounted(load);watch(section,load);async function saveProduct(){try{await api('/admin/products',{method:'POST',body:JSON.stringify(form.value)});showProduct.value=false;router.push('/admin/products');load()}catch(e:any){error.value=e.message}}</script>
<template><div class="admin"><aside class="admin-side"><RouterLink to="/" class="brand">SHOPORA<span>ADMIN</span></RouterLink><p>OPERATIONS</p><RouterLink to="/admin">Overview</RouterLink><RouterLink to="/admin/orders">Orders</RouterLink><RouterLink to="/admin/products">Products</RouterLink><RouterLink to="/admin/categories">Categories</RouterLink><div class="admin-user"><b>{{session.user?.name}}</b><small>{{session.user?.email}}</small><RouterLink to="/">← Storefront</RouterLink></div></aside><main class="admin-main"><header><div><small>PRIVATE WORKSPACE</small><h1>{{section==='overview'?'Good morning.':section[0].toUpperCase()+section.slice(1)}}</h1></div><button v-if="section==='products'" class="admin-button" @click="showProduct=true">+ New product</button></header><p v-if="error" class="notice">{{error}}</p><template v-if="section==='overview'&&data"><div class="metrics"><article><small>PAID REVENUE</small><b>{{idr(data.paidRevenue)}}</b></article><article><small>TOTAL ORDERS</small><b>{{data.totalOrders}}</b></article><article><small>ACTIVE PRODUCTS</small><b>{{data.activeProducts}}</b></article><article><small>PENDING ORDERS</small><b>{{data.pendingOrders}}</b></article></div><section class="admin-panel"><h2>Recent orders</h2><table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr></thead><tbody><tr v-for="o in data.recentOrders"><td>{{o.orderNumber}}</td><td>{{o.user.name}}</td><td>{{idr(o.totalAmount)}}</td><td><span class="status" :class="o.paymentStatus.toLowerCase()">{{o.paymentStatus}}</span></td></tr></tbody></table></section><section class="admin-panel"><h2>Low inventory</h2><div class="low-stock"><p v-for="p in data.lowStock"><span>{{p.name}}</span><b>{{p.stock}} left</b></p><p v-if="!data.lowStock.length">Inventory levels are healthy.</p></div></section></template><section v-else-if="data" class="admin-panel"><h2>{{section==='products'?'Catalog products':section==='orders'?'All orders':'Product categories'}}</h2><table v-if="section==='products'"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>State</th></tr></thead><tbody><tr v-for="p in data"><td><b>{{p.name}}</b></td><td>{{p.sku}}</td><td>{{p.category.name}}</td><td>{{idr(p.price)}}</td><td :class="p.stock<=5?'danger':''">{{p.stock}}</td><td>{{p.isActive?'Active':'Archived'}}</td></tr></tbody></table><table v-else-if="section==='orders'"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Payment</th><th>Fulfillment</th></tr></thead><tbody><tr v-for="o in data"><td>{{o.orderNumber}}</td><td>{{o.user.name}}</td><td>{{o.items.length}}</td><td>{{idr(o.totalAmount)}}</td><td><span class="status" :class="o.paymentStatus.toLowerCase()">{{o.paymentStatus}}</span></td><td>{{o.fulfillmentStatus}}</td></tr></tbody></table><table v-else><thead><tr><th>Name</th><th>Slug</th><th>Products</th><th>Status</th></tr></thead><tbody><tr v-for="c in data"><td>{{c.name}}</td><td>{{c.slug}}</td><td>{{c._count.products}}</td><td>{{c.isActive?'Active':'Archived'}}</td></tr></tbody></table></section></main><div v-if="showProduct" class="modal"><form class="admin-modal" @submit.prevent="saveProduct"><button type="button" class="close" @click="showProduct=false">×</button><small>PRODUCT CATALOG</small><h2>Add a new product</h2><input v-model="form.name" placeholder="Product name" required/><input v-model="form.sku" placeholder="SKU" required/><select v-model="form.categoryId" required><option value="" disabled>Choose category</option><option v-for="c in (data??[])" v-if="section==='products'" :value="c.categoryId">{{c.category?.name}}</option></select><p class="help">Open Categories first and copy a category is intentionally avoided. Please select after loading catalog (category values derive from products).</p><textarea v-model="form.description" placeholder="Description (at least 10 characters)" required/><input v-model.number="form.price" type="number" min="0" placeholder="Price" required/><input v-model.number="form.stock" type="number" min="0" placeholder="Stock" required/><input v-model="form.imageUrl" type="url" placeholder="Image URL"/><button class="admin-button">Create product</button></form></div></div></template>
